/*
 * Shared element inventory for the /reference section: the generated
 * index plus the hand-authored supplement, one flat sorted list, and the
 * slug/href helpers every consumer (index, element pages, sitemap) shares
 * so the paths cannot drift.
 *
 * data/elements.json is generated by scripts/build-elements-index.mjs in
 * noizu-labs-ml/npl-enhanced-content from spec/schema/*.md — never
 * hand-edit it. data/reference-glossary.ts supplements the eight elements
 * the generator cannot emit (see its header).
 */

import elementsIndex from "@/data/elements.json";
import bundlesIndex from "@/data/bundles.json";
import {
  GLOSSARY_TAGS,
  type TagRecord,
} from "@/data/reference-glossary";

type ElementsIndex = {
  $comment: string;
  specVersion: string;
  generatedFrom: string[];
  tagCount: number;
  tags: TagRecord[];
  gaps: Array<{ tag: string; missing: string[] }>;
};

const INDEX = elementsIndex as ElementsIndex;

/*
 * Shipped-runtime provenance per tag, generated from the built artefacts in
 * public/semtext/ by scripts/build-bundle-map.mjs (which file provides the
 * tag: semtext.js, the lazy loader and its chunk, or nothing).
 * Regenerate that JSON whenever public/semtext/ is re-synced.
 */
export interface BundleEntry {
  file: string;
  detail: string;
  /** The lazy chunk that provides the tag (`chunks/<tag>.js`), when the
   * entry is the lazy loader. The render pane loads npl chunks directly
   * (pane-scoped element upgrade) instead of the npl namespace loader,
   * which auto-scans the whole document with no off switch. */
  chunk?: string;
}

export interface TagBundle {
  shipped: boolean;
  bundles?: BundleEntry[];
  sharedWith?: string;
  /**
   * Zero-JS by contract and painted by the shipped theme CSS: the shipped
   * vocabulary stylesheet styles the authored markup, so the render pane
   * mounts without any runtime (sem-event / sem-chronology / sem-procedure
   * / sem-step, and display-only npl tags once their CSS blocks ship).
   * Derived from the CSS selectors by scripts/build-bundle-map.mjs — never
   * a hand list.
   */
  cssOnly?: boolean;
  note?: string;
}

const BUNDLES = bundlesIndex as { tags: Record<string, TagBundle> };

/** Which shipped JS file(s) provide a tag, or undefined if the map predates it. */
export function bundlesFor(name: string): TagBundle | undefined {
  return BUNDLES.tags[name];
}

/**
 * Class-form alias wiring emitted by scripts/build-bundle-map.mjs: the one
 * extra bundle file a namespace's class-form examples need beyond their
 * tag's own runtime (a `div.sem-<tag>` host enhances only under the full
 * bundle; npl class hosts upgrade under the tag's own npl runtime). Empty
 * until that file ships in public/semtext/.
 */
export function aliasRuntime(): Record<string, string> {
  return (BUNDLES as { aliasRuntime?: Record<string, string> }).aliasRuntime ?? {};
}

/** Spec version the generated half of the inventory was built from. */
export const SPEC_VERSION = INDEX.specVersion;

/** Every element, generated and hand-authored, sorted by name. */
export const ALL_TAGS: TagRecord[] = [...INDEX.tags, ...GLOSSARY_TAGS].sort(
  (a, b) => a.name.localeCompare(b.name),
);

export const SEM_TAGS = ALL_TAGS.filter((t) => t.family === "sem");
export const NPL_TAGS = ALL_TAGS.filter((t) => t.family === "npl");

/** Schema fields the generator could not find, per tag (usually empty). */
export const GAP_MISSING = new Map(INDEX.gaps.map((g) => [g.tag, g.missing]));

/*
 * URL slug for an element page: /reference/<slug>/. Every generated and
 * hand-authored tag name is already lowercase ASCII with hyphens (they are
 * XML names, lowercase by convention), so the slug IS the name; the
 * normalisation below is a guard — if a future name ever needed rewriting
 * the mismatch throws at build time rather than shipping a broken link.
 */
export function tagSlug(name: string): string {
  const slug = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  if (slug !== name) {
    throw new Error(`tag name is not URL-safe as-is: ${name} -> ${slug}`);
  }
  return slug;
}

/** Canonical href of an element's own page. */
export function tagHref(name: string): string {
  return `/reference/${tagSlug(name)}/`;
}

/** The element a slug belongs to, or undefined. */
export function tagBySlug(slug: string): TagRecord | undefined {
  return ALL_TAGS.find((t) => tagSlug(t.name) === slug);
}
